<script setup>
import {ref,computed,watch} from 'vue';
import {scripts} from '../data';
const left=ref(2),right=ref(4),axis=ref('结构'),note=ref(''),saved=ref(false),notice=ref('');
const dimensions={结构:['轮廓与部件位置','字内空间与布局','修长、匀整的结构','横向舒展的形态','端正的结构与重心','疏密变化与笔势联系'],线条:['契刻痕迹与转折','粗细与形态变化','圆转、均匀的线条','主笔展开与收笔','清晰的点画关系','连贯与节奏变化'],观察:['先描述你看到的轮廓','将单字与整体排列一起看','比较左右与上下的呼应','留意主笔如何影响重心','找出主笔与内部留白','区分行书、草书各自的特点']};
const prompt=computed(()=>`请对比${scripts[left.value].name}与${scripts[right.value].name}在${axis.value}方面的特点。我的观察：${note.value.trim()||'暂未记录，请给我三个观察问题。'}。请区分确定信息与需要核实的内容。`);
const key=computed(()=>`zisu.observation.${left.value}.${right.value}`);
function restore(){try{note.value=localStorage.getItem(key.value)||''}catch{note.value=''}saved.value=false}
watch(key,restore,{immediate:true});watch(note,()=>saved.value=false);
function save(){try{localStorage.setItem(key.value,note.value);saved.value=true;notice.value='观察已保存在当前浏览器。'}catch{notice.value='当前浏览器无法保存，请复制观察内容。'}}
</script>
<template><section class="observation-lab"><div class="lab-heading"><div><span class="sub">INTERACTIVE STUDIO / 观字实验室</span><h2>把“觉得不同”，<br>变成说得清的发现。</h2></div><p>选两种书体，从一个维度开始比较。写下观察，再带着问题向 AI 追问。</p></div><div class="lab-layout"><div><div class="lab-tabs" aria-label="观察维度"><button v-for="a in ['结构','线条','观察']" :key="a" :aria-pressed="axis===a" @click="axis=a">{{a}}</button></div><div class="specimen-grid"><article v-for="side in ['left','right']" :key="side" class="specimen"><label :for="'compare-'+side">{{side==='left'?'对照 A':'对照 B'}}</label><select :id="'compare-'+side" :value="side==='left'?left:right" @change="side==='left'?left=Number($event.target.value):right=Number($event.target.value)"><option v-for="(s,i) in scripts" :key="s.name" :value="i">{{s.name}}</option></select><div class="specimen-glyph" aria-hidden="true">{{scripts[side==='left'?left:right].glyph}}</div><small>现代装饰字 · 非历史字形</small><h3>{{scripts[side==='left'?left:right].title}}</h3><p>{{dimensions[axis][side==='left'?left:right]}}</p><RouterLink :to="'/scripts/'+(side==='left'?left:right)">阅读专题 ↗</RouterLink></article></div><p v-if="left===right" class="quiet" role="status">两侧相同，换一种书体可以更容易比较。</p></div><aside class="observation-note"><span class="sub">MY OBSERVATION</span><h3>留下一条自己的发现</h3><label for="observation">可以描述重心、比例、线条或留白</label><textarea id="observation" v-model="note" maxlength="600" rows="6" placeholder="例如：我想了解两种书体在结构比例上的差别……"></textarea><div class="note-count">{{note.length}} / 600</div><button class="outline" @click="save">{{saved?'已保存 ✓':'保存观察'}}</button><p v-if="notice" class="quiet" role="status">{{notice}}</p><RouterLink class="primary" :to="{path:'/chat',query:{q:prompt,script:scripts[left].name+'、'+scripts[right].name}}">带着观察问 AI ↗</RouterLink><p class="quiet">比较提示用于入门。真实字形仍需结合来源明确的作品观察。</p></aside></div></section></template>
